# Surah Hud (chapter 11) — part 2: ayat 11-20 (IDs 1484-1493)
SURAH = 11

ENTRIES = {
1484: (
"مگر — وہ لوگ — جو — صبر — کرتے ہیں — اور — نیک عمل — کرتے ہیں — یہی لوگ — ان کے لیے — مغفرت — اور — عظیم اجر — ہے",
"""۱۔ صبر اور نیک عمل — مغفرت اور اجرِ عظیم کا ذریعہ۔
۲۔ ’’إِلَّا الَّذِينَ صَبَرُوا وَعَمِلُوا الصَّالِحَاتِ أُولَٰئِكَ لَهُم مَّغْفِرَۃٌ وَأَجْرٌ كَبِيرٌ‘‘ — مگر — وہ لوگ — جو — صبر — کرتے ہیں — اور — نیک عمل — کرتے ہیں — یہی لوگ — ان کے لیے — مغفرت — اور — عظیم اجر — ہے — یعنی صبر اور نیک عمل — کرنے والوں کو — مغفرت اور اجرِ عظیم — ملتا ہے۔
۳۔ عملی سبق: صبر اور عمل — دونوں — اپناؤ۔"""
),
1485: (
"شاید — آپؐ — اس — کے کچھ حصے — کو — جو — آپ — کی طرف — وحی کیا جاتا ہے — چھوڑ دیں — اور — آپ — کا — سینہ — اس سے — تنگ — ہو جائے — اس — لیے کہ — وہ کہتے ہیں — اس پر — کوئی خزانہ — کیوں نہیں اتارا گیا — یا — اس — کے ساتھ — کوئی فرشتہ — کیوں نہیں آیا — بے شک — آپؐ — صرف نصیحت کرنے والے — ہیں — اور — اللہ — ہر چیز — پر — نگہبان — ہے",
"""۱۔ نبیؐ — کا دل تنگ — کفار کے مطالبوں سے۔
۲۔ ’’فَلَعَلَّكَ تَارِكٌ بَعْضَ مَا يُوحَىٰ إِلَيْكَ وَضَائِقٌ بِهِ صَدْرُكَ أَن يَقُولُوا لَوْلَا أُنزِلَ عَلَيْهِ كَنزٌ أَوْ جَاءَ مَعَهُ مَلَكٌ إِنَّمَا أَنتَ نَذِيرٌ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ وَكِيلٌ‘‘ — شاید — آپؐ — اس — کے کچھ حصے — کو — جو — آپ — کی طرف — وحی کیا جاتا ہے — چھوڑ دیں — اور — آپ — کا — سینہ — اس سے — تنگ — ہو جائے — اس — لیے کہ — وہ کہتے ہیں — اس پر — کوئی خزانہ — کیوں نہیں اتارا گیا — یا — اس — کے ساتھ — کوئی فرشتہ — کیوں نہیں آیا — بے شک — آپؐ — صرف نصیحت کرنے والے — ہیں — اور — اللہ — ہر چیز — پر — نگہبان — ہے — یعنی آپؐ — کفار کے مطالبوں کی وجہ سے — وحی کی کچھ باتیں — چھوڑنے — کے قریب پہنچ گئے؛ آپؐ — صرف — ڈرانے والے ہیں — اور اللہ — ہر چیز — پر نگہبان ہے۔
۳۔ عملی سبق: آپؐ — صرف — نذیر ہیں؛ آپؐ — پر بوجھ — نہ ڈالو۔"""
),
1486: (
"یا — وہ کہتے ہیں — اس — نے — اسے — گھڑ — لیا — کہدو — تو — اس — جیسی — دس سورتیں — گھڑ کر — لاؤ — اور — اللہ کے سوا — جسے — تم — بلا سکو — بلاؤ — اگر — تم سچے ہو",
"""۱۔ قرآن — جیسی دس سورتیں — گھڑی جا سکتی ہوں — غیر ممکن۔
۲۔ ’’أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِعَشْرِ سُوَرٍ مِّثْلِهِ مُفْتَرَيَاتٍ وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ‘‘ — یا — وہ کہتے ہیں — اس — نے — اسے — گھڑ — لیا — کہدو — تو — اس — جیسی — دس سورتیں — گھڑ کر — لاؤ — اور — اللہ کے سوا — جسے — تم — بلا سکو — بلاؤ — اگر — تم سچے ہو — یعنی اگر — قرآن — گھڑا ہوا ہے — تو اس جیسی — دس سورتیں — لاؤ — اور مدد کے لیے — جو — بلا سکو — بلاؤ؛ یہ — غیر ممکن — ہے۔
۳۔ عملی سبق: قرآن — جیسا کلام — ممکن نہیں؛ اسے — اپناؤ۔"""
),
1487: (
"پس — اگر — وہ — تم — کو — جواب نہ دیں — تو — جان لو — کہ — یہ — اللہ کے علم — سے نازل ہوا — اور — اس — کے سوا — کوئی — معبود نہیں — پس — کیا — تم — مسلمان — ہو جاؤ گے",
"""۱۔ قرآن — جواب — نہ ملے — تو — اس کی حقانیت — معلوم ہوتی ہے۔
۲۔ ’’فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ فَاعْلَمُوا أَنَّمَا أُنزِلَ بِعِلْمِ اللَّهِ وَأَن لَّا إِلَٰهَ إِلَّا هُوَ فَهَلْ أَنتُم مُّسْلِمُونَ‘‘ — پس — اگر — وہ — تم — کو — جواب نہ دیں — تو — جان لو — کہ — یہ — اللہ کے علم — سے نازل ہوا — اور — اس — کے سوا — کوئی — معبود نہیں — پس — کیا — تم — مسلمان — ہو جاؤ گے — یعنی اگر — جواب — نہ دیں — تو جان لو — یہ — اللہ کے علم سے — نازل ہوا ہے — اس کے سوا — معبود — نہیں؛ اب بھی مسلمان — ہو جاؤ۔
۳۔ عملی سبق: حق — ثابت ہو جائے — تو — انکار — بے وقوفی ہے۔"""
),
1488: (
"جو — شخص — دنیا کی زندگی — اور — اس — کی — زینت — چاہتا ہے — ہم — اس — کو — اس کے عملوں — کا بدلہ — دنیا میں — پورا — دیتے ہیں — اور — وہ — اس — میں — کم — نہیں دیے جاتے",
"""۱۔ دنیا — کے طالب — کو — دنیا میں بدلہ ملتا ہے۔
۲۔ ’’مَن كَانَ يُرِيدُ الْحَيَاۃَ الدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَالَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ‘‘ — جو — شخص — دنیا کی زندگی — اور — اس — کی — زینت — چاہتا ہے — ہم — اس — کو — اس کے عملوں — کا بدلہ — دنیا میں — پورا — دیتے ہیں — اور — وہ — اس — میں — کم — نہیں دیے جاتے — یعنی جو شخص — دنیا کی زینت چاہتا ہے — ہم اسے — دنیا میں — اس کے اعمال کا پورا بدلہ — دیتے ہیں — کم — نہیں دیتے۔
۳۔ عملی سبق: نیت — واضح کرو؛ دنیا — ملتی ہے — مگر — آخرت — اپنی طرف — بلا رہی ہے۔"""
),
1489: (
"یہ — وہ لوگ ہیں — جن — کے لیے — آخرت میں — سوائے آگ کے — کچھ نہیں — اور — ان — کا — دنیا میں جو کیا — وہ — ضائع — ہوا — اور — ان — کا عمل — باطل — ہوا",
"""۱۔ دنیا — میں بدلہ پانے والوں — کے لیے — آخرت میں صرف آگ۔
۲۔ ’’أُولَٰئِكَ الَّذِينَ لَيْسَ لَهُمْ فِي الْآخِرَۃِ إِلَّا النَّارُ وَحَبِطَ مَا صَنَعُوا فِيهَا وَبَاطِلٌ مَّا كَانُوا يَعْمَلُونَ‘‘ — یہ — وہ لوگ ہیں — جن — کے لیے — آخرت میں — سوائے آگ کے — کچھ نہیں — اور — ان — کا — دنیا میں جو کیا — وہ — ضائع — ہوا — اور — ان — کا عمل — باطل — ہوا — یعنی دنیا کی زینت چاہنے والوں — کے لیے — آخرت میں — سوائے آگ — کے کچھ نہیں؛ ان کے اعمال — ضائع — ہوئے۔
۳۔ عملی سبق: دنیا کی محبت — آخرت کو — برباد کر دیتی ہے۔"""
),
1490: (
"کیا — وہ — جو — اپنے رب کی طرف سے — دلیل — پر ہے — اور — اس — کے بعد — ایک گواہ اس کے ساتھ — قرآن — ہے — اور — اس — سے پہلے — موسیٰ — کی — کتاب — امام اور رحمت کے طور پر — ایسے لوگ — اس — پر ایمان لاتے ہیں — اور — جو — گروہوں میں سے — اس — سے انکار کرے — تو — اس کا وعدہ — آگ ہے — پس — آپ — اس — کے بارے میں — شک — میں — نہ ہوں — بے شک — یہ — حق — ہے — آپ — کے رب کی طرف سے — لیکن — اکثر لوگ — ایمان — نہیں لاتے",
"""۱۔ دلیلِ ربانی — اور — موسیٰؑ کی کتاب کی تصدیق۔
۲۔ ’’أَفَمَن كَانَ عَلَىٰ بَيِّنَۃٍ مِّن رَّبِّهِ وَيَتْلُوهُ شَاهِدٌ مِّنْهُ وَمِن قَبْلِهِ كِتَابُ مُوسَىٰ إِمَامًا وَرَحْمَۃً أُولَٰئِكَ يُؤْمِنُونَ بِهِ وَمَن يَكْفُرْ بِهِ مِنَ الْأَحْزَابِ فَالنَّارُ مَوْعِدُهُ فَلَا تَكُ فِي مِرْيَۃٍ مِّنْهُ إِنَّهُ الْحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ‘‘ — کیا — وہ — جو — اپنے رب کی طرف سے — دلیل — پر ہے — اور — اس — کے بعد — ایک گواہ اس کے ساتھ — قرآن — ہے — اور — اس — سے پہلے — موسیٰ — کی — کتاب — امام اور رحمت کے طور پر — ایسے لوگ — اس — پر ایمان لاتے ہیں — اور — جو — گروہوں میں سے — اس — سے انکار کرے — تو — اس کا وعدہ — آگ ہے — پس — آپ — اس — کے بارے میں — شک — میں — نہ ہوں — بے شک — یہ — حق — ہے — آپ — کے رب کی طرف سے — لیکن — اکثر لوگ — ایمان — نہیں لاتے — یعنی قرآن — حق ہے — اپنے رب کی دلیل — اور — موسیٰؑ کی کتاب — سچے دین کی تصدیق کرتی ہے — گروہوں میں سے — انکار کرنے والوں کا وعدہ — آگ ہے (بعض روایات میں ’’وَيَتْلُوهُ شَاهِدٌ مِّنْهُ‘‘ میں شاہد سے مراد — امیر المومنین علیؑ — لی جاتی ہے)۔
۳۔ عملی سبق: دلیل — اور — قرآن — دونوں موجود ہیں؛ ایمان — لاؤ۔"""
),
1491: (
"اور — اس — سے بڑھ کر — ظالم کون ہے — جس نے — اللہ — پر جھوٹ — گھڑا — یہی لوگ — اپنے رب کے سامنے — پیش کیے جائیں گے — اور — گواہ — کہیں گے — یہی وہ لوگ — ہیں — جنہوں نے — اپنے رب — پر — جھوٹ بولا — سنو — ظالموں — پر — اللہ کی لعنت — ہے",
"""۱۔ اللہ پر جھوٹ گھڑنے والا — سب سے ظالم — اور — لعنت کا مستحق۔
۲۔ ’’وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا أُولَٰئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ الْأَشْهَادُ هَٰؤُلَاءِ الَّذِينَ كَذَبُوا عَلَىٰ رَبِّهِمْ أَلَا لَعْنَۃُ اللَّهِ عَلَى الظَّالِمِينَ‘‘ — اور — اس — سے بڑھ کر — ظالم کون ہے — جس نے — اللہ — پر جھوٹ — گھڑا — یہی لوگ — اپنے رب کے سامنے — پیش کیے جائیں گے — اور — گواہ — کہیں گے — یہی وہ لوگ — ہیں — جنہوں نے — اپنے رب — پر — جھوٹ بولا — سنو — ظالموں — پر — اللہ کی لعنت — ہے — یعنی اللہ پر جھوٹ گھڑنا — سب — سے بڑا ظلم ہے — سزا — اللہ کی لعنت — ہے۔
۳۔ عملی سبق: اللہ پر جھوٹ — مت گھڑو — لعنت — بہت — بھاری ہے۔"""
),
1492: (
"جو — اللہ کی راہ — سے روکتے ہیں — اور — اس — میں — ٹیڑھا — ڈھونڈتے ہیں — اور — آخرت — کے — منکر — ہیں",
"""۱۔ راستے کو ٹیڑھا — کرنے والے — آخرت کے منکر — ظالموں کی — پہچان۔
۲۔ ’’الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَۃِ هُمْ كَافِرُونَ‘‘ — جو — اللہ کی راہ — سے روکتے ہیں — اور — اس — میں — ٹیڑھا — ڈھونڈتے ہیں — اور — آخرت — کے — منکر — ہیں — یعنی وہ — اللہ کی راہ سے — روکتے ہیں — اور — اس میں — ٹیڑھا — تلاش کرتے ہیں — اور — آخرت کے — منکر — ہیں۔
۳۔ عملی سبق: راہِ خدا — میں — ٹیڑھا — تلاش کرنے والوں سے — بچو۔"""
),
1493: (
"یہ لوگ — زمین میں — عاجز — نہیں کر سکتے — اور — نہ — اللہ کے سوا — ان — کا — کوئی — مددگار — ہے — ان — پر — عذاب — دوہرا — کیا جائے گا — وہ سن — نہ — سکتے تھے — اور — نہ — دیکھ — سکتے تھے",
"""۱۔ ظالموں — کے لیے — دوہرا عذاب — اللہ کو عاجز — نہیں کر سکتے۔
۲۔ ’’أُولَٰئِكَ لَمْ يَكُونُوا مُعْجِزِينَ فِي الْأَرْضِ وَمَا كَانَ لَهُم مِّن دُونِ اللَّهِ مِنْ أَوْلِيَاءَ يُضَاعَفُ لَهُمُ الْعَذَابُ مَا كَانُوا يَسْتَطِيعُونَ السَّمْعَ وَمَا كَانُوا يُبْصِرُونَ‘‘ — یہ لوگ — زمین میں — عاجز — نہیں کر سکتے — اور — نہ — اللہ کے سوا — ان — کا — کوئی — مددگار — ہے — ان — پر — عذاب — دوہرا — کیا جائے گا — وہ سن — نہ — سکتے تھے — اور — نہ — دیکھ — سکتے تھے — یعنی یہ ظالموں — کو زمیں میں عاجز — نہیں کر سکتے — اللہ کے سوا — کوئی مددگار — نہیں — ان پر عذاب — دوبارہ — کیا جائے گا — وہ نہ — سچائی سن سکتے تھے — اور — نہ — حق دیکھ سکتے تھے۔
۳۔ عملی سبق: حق — سننے سے گریز — دوہرا عذاب — کا سبب ہے۔"""
),
}
